import * as React from 'react'
import { graphql, Link } from 'gatsby'
import { IGatsbyImageData, GatsbyImage, getImage } from 'gatsby-plugin-image'

import "../../scss/main.scss"

import Header from "../../components/Header"
import Footer from "../../components/Footer"
import AccentDots from "../../components/AccentDots"

interface ImageNode {
  name: string
  childImageSharp: {
    thumb: IGatsbyImageData
  }
}

interface PageProps {
  data: {
    images: { nodes: ImageNode[] }
    logo: { nodes: ImageNode[] }
  }
}

const techStack = [
  'Mongo', 'Express', 'Angular', 'Node',
  'Facebook Auth', 'NgFileUpload', 'AWS',
  'HTML5', 'CSS3', 'Skeleton CSS', 'jQuery', 'jQuery Masonry'
]

const PictureMePage: React.FC<PageProps> = ({ data }) => {
  const [spotlightIndex, setSpotlightIndex] = React.useState<number | null>(null)
  const [dragY, setDragY] = React.useState(0)
  const [isDragging, setIsDragging] = React.useState(false)
  const [zoomScale, setZoomScale] = React.useState(1)
  const [zoomOrigin, setZoomOrigin] = React.useState({ x: 50, y: 50 })
  const initialPinchDistance = React.useRef(0)
  const lastScale = React.useRef(1)
  const touchStartY = React.useRef(0)

  const logo = data.logo.nodes[0] ? getImage(data.logo.nodes[0].childImageSharp.thumb) : null

  const spotlightImages = data.images.nodes.filter(n => n.name !== 'picture-me-logo-small')
  const wireframe = spotlightImages.find(n => n.name === 'pm_wireframe')
  const screenshot = spotlightImages.find(n => n.name === 'pm_screen')

  const orderedImages = [wireframe, screenshot].filter(Boolean) as ImageNode[]

  const openSpotlight = (node: ImageNode) => {
    const idx = orderedImages.indexOf(node)
    if (idx >= 0) setSpotlightIndex(idx)
  }

  const dismissThreshold = 120

  const getPinchDistance = (touches: React.TouchList) => {
    const dx = touches[0].clientX - touches[1].clientX
    const dy = touches[0].clientY - touches[1].clientY
    return Math.sqrt(dx * dx + dy * dy)
  }

  const handleTouchStart = (e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      initialPinchDistance.current = getPinchDistance(e.touches)
      lastScale.current = zoomScale
    } else if (e.touches.length === 1 && zoomScale <= 1) {
      touchStartY.current = e.touches[0].clientY
      setIsDragging(true)
    }
  }

  const handleTouchMove = (e: React.TouchEvent) => {
    if (e.touches.length === 2) {
      const dist = getPinchDistance(e.touches)
      const scale = Math.max(1, Math.min(4, lastScale.current * (dist / initialPinchDistance.current)))
      const midX = ((e.touches[0].clientX + e.touches[1].clientX) / 2 / window.innerWidth) * 100
      const midY = ((e.touches[0].clientY + e.touches[1].clientY) / 2 / window.innerHeight) * 100
      setZoomScale(scale)
      setZoomOrigin({ x: midX, y: midY })
    } else if (e.touches.length === 1 && zoomScale <= 1) {
      const delta = e.touches[0].clientY - touchStartY.current
      if (delta > 0) {
        setDragY(delta)
      }
    }
  }

  const handleTouchEnd = () => {
    if (zoomScale <= 1) {
      setIsDragging(false)
      if (dragY > dismissThreshold) {
        setSpotlightIndex(null)
        setZoomScale(1)
      }
      setDragY(0)
    }
  }

  return (
    <div className="container">
      <Header />

      <div className="case-study__hero">
        <Link to="/developer" className="back-link">&larr; Back to Developer</Link>
        <h1>Picture Me</h1>
        {logo && (
          <div className="case-study__logo-wrap">
            <GatsbyImage image={logo} alt="Picture Me logo" className="case-study__logo" />
          </div>
        )}
        <AccentDots />
      </div>

      <div className="case-study__body">
        <section className="case-study__section">
          <h2>Vision</h2>
          <p>
            We are all unique, built up of many layers &mdash; images. We live our lives with
            snapshots of our past and present. Picture Me is an interactive site whereby the user
            logs in via Facebook and chooses 25 images that represent different stages in their lives.
          </p>
          <p>
            Once all the images are uploaded they form a 5&times;5 square grid, and the user's Facebook
            profile picture becomes the main image covering the entire grid. You only see the individual
            image when you hover over a section of the profile picture.
          </p>
          <p>
            This represents an interaction in life with someone you don't know &mdash; you don't
            necessarily see their life stages, and it's only by chatting that you shed light on an
            experience, which in turn reveals an image. The final piece contains all the visuals that
            make us unique.
          </p>
          <p>
            All branding and visual assets including the logo were designed and
            created in Adobe Illustrator.
          </p>
          <p>
            Built during the General Assembly Web Development Immersive course.
          </p>
        </section>

        <section className="case-study__section">
          <h2>Wireframes</h2>
          {wireframe && (() => {
            const img = getImage(wireframe.childImageSharp.thumb)
            return img ? (
              <div className="case-study__image-wrap" onClick={() => openSpotlight(wireframe)}>
                <GatsbyImage image={img} alt="Picture Me wireframes" className="case-study__image" />
              </div>
            ) : null
          })()}
        </section>

        <section className="case-study__section">
          <h2>Final Product</h2>
          {screenshot && (() => {
            const img = getImage(screenshot.childImageSharp.thumb)
            return img ? (
              <div className="case-study__image-wrap" onClick={() => openSpotlight(screenshot)}>
                <GatsbyImage image={img} alt="Picture Me screenshot" className="case-study__image" />
              </div>
            ) : null
          })()}
        </section>

        <section className="case-study__section">
          <h2>Tech Stack</h2>
          <div className="case-study__pills">
            {techStack.map((tech) => (
              <span key={tech} className="case-study__pill">{tech}</span>
            ))}
          </div>
        </section>

        <section className="case-study__section">
          <h2>User Stories</h2>
          <ul className="case-study__stories">
            <li>A user will be able to login via Facebook</li>
            <li>A user's Facebook profile picture will be used as the main image in the grid</li>
            <li>A user is able to select 25 meaningful pictures from their computer to be placed on the grid</li>
            <li>A user is able to delete their Picture Me in order to start again</li>
          </ul>
        </section>

        <section className="case-study__section">
          <h2>Future Aims</h2>
          <ul className="case-study__stories">
            <li>A user would be able to select the 25 images from their Facebook account</li>
            <li>A user will have the ability to share the finished image</li>
          </ul>
        </section>
      </div>

      {spotlightIndex !== null && (() => {
        const node = orderedImages[spotlightIndex]
        const image = getImage(node.childImageSharp.thumb)
        const opacity = Math.max(0.2, 1 - dragY / 400)

        return (
          <div
            className="case-study__spotlight"
            onClick={() => { setSpotlightIndex(null); setZoomScale(1) }}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
            style={{ background: `rgba(0, 0, 0, ${opacity * 0.9})` }}
          >
            <div className="case-study__spotlight-hint">Swipe down to close · Pinch to zoom</div>
            <div
              className="case-study__spotlight-content"
              onClick={(e) => {
                e.stopPropagation()
                if (zoomScale > 1) setZoomScale(1)
              }}
              style={{
                transform: `translateY(${dragY}px) scale(${zoomScale})`,
                transformOrigin: `${zoomOrigin.x}% ${zoomOrigin.y}%`,
                transition: isDragging ? 'none' : 'transform 0.3s ease',
              }}
            >
              {image && (
                <GatsbyImage
                  image={image}
                  alt={node.name === 'pm_wireframe' ? 'Picture Me wireframes' : 'Picture Me screenshot'}
                  className="case-study__spotlight-image"
                />
              )}
            </div>
          </div>
        )
      })()}

      <Footer />
    </div>
  )
}

export const pageQuery = graphql`
  query PictureMeQuery {
    images: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "picture-me" }
        extension: { in: ["png", "jpg", "jpeg"] }
        name: { ne: "picture-me-logo-small" }
      }
      sort: { name: ASC }
    ) {
      nodes {
        name
        childImageSharp {
          thumb: gatsbyImageData(width: 800, placeholder: BLURRED)
        }
      }
    }
    logo: allFile(
      filter: {
        sourceInstanceName: { eq: "developer" }
        relativeDirectory: { eq: "picture-me" }
        name: { eq: "picture-me-logo-small" }
      }
    ) {
      nodes {
        name
        childImageSharp {
          thumb: gatsbyImageData(width: 200, placeholder: BLURRED)
        }
      }
    }
  }
`

export default PictureMePage
